action.command:
node --input-type=module -e '
import { readFileSync } from "node:fs";
const orig = readFileSync(".github/workflows/oracle-reset-database.yml","utf8");
const code = (src) => src.split("\n").filter((l)=>!l.trim().startsWith("#") && !l.trim().startsWith("description:")).join("\n");
function t1(src){ const text=code(src);
  const triggers = text.match(/^on:\n((?:[ ]{2,}.*\n?)+)/mu)?.[1] ?? "";
  const m = triggers.match(/^ {2}[a-z_]+:/gmu);
  if (JSON.stringify(m)!==JSON.stringify(["  workflow_dispatch:"])) return "FAIL triggers "+JSON.stringify(m);
  if(!/^ {4}if: \$\{\{ github\.ref == '"'"'refs\/heads\/main'"'"' \}\}$/mu.test(text)) return "FAIL main-if";
  if(!/^ {2}group: oracle-production$/mu.test(text)) return "FAIL group";
  if(!/runs-on: \[self-hosted, Linux, ARM64, kotobawork-oci\]/u.test(text)) return "FAIL runs-on";
  if(/continue-on-error|if: always|if: failure/u.test(text)) return "FAIL coe";
  if(text.match(/^ {6,}if:/gmu)!==null) return "FAIL step-if";
  return "pass"; }
function t2(src){ const text=code(src);
  if(!/^ {6}CONFIRM: \$\{\{ inputs\.confirm \}\}$/mu.test(text)) return "FAIL confirm-env";
  const c=text.indexOf(`run: test "$CONFIRM" = "WIPE-ORACLE-DATABASE"`), d=text.indexOf("pg_dump -U postgres -d nihongo_bjt -Fc"), v=text.indexOf("pg_restore --list"), x=text.indexOf("DROP DATABASE IF EXISTS nihongo_bjt WITH (FORCE)");
  if(!(c>-1 && d>c && v>d && x>v)) return "FAIL order";
  if((text.match(/DROP DATABASE/gu)||[]).length!==1) return "FAIL dropcount";
  if(!text.includes("flock -n 9")) return "FAIL flock";
  if(/rm\s+-rf|docker\s+volume|system\s+prune|\/srv\/kotobawork\/data\/(postgres|media)/u.test(text)) return "FAIL destructive";
  return "pass"; }
const muts = {
  "baseline": orig,
  "M1 confirm || true": orig.replace(`run: test "$CONFIRM" = "WIPE-ORACLE-DATABASE"`, `run: test "$CONFIRM" = "WIPE-ORACLE-DATABASE" || true`),
  "M2 step - if: false": orig.replace(`      - name: Require typed confirmation\n        run:`, `      - if: false\n        name: Require typed confirmation\n        run:`),
  "M3 step env override": orig.replace(`        run: test "$CONFIRM"`, `        env: { CONFIRM: WIPE-ORACLE-DATABASE }\n        run: test "$CONFIRM"`),
  "M4 push after blank line": orig.replace(`        type: string\n`, `        type: string\n\n  push:\n    branches: [main]\n`),
  "M5 flow-style if on step": orig.replace(`      - name: Back up, drop and recreate the database\n`, `      - { name: x, if: false, run: "true" }\n      - name: Back up, drop and recreate the database\n`),
  "M6 drop flock (use flock || true)": orig.replace("flock -n 9", "flock -n 9 || true"),
  "M7 drop backup validation (|| true)": orig.replace("pg_restore --list < \"$dump.partial\" > /dev/null", "pg_restore --list < \"$dump.partial\" > /dev/null || true"),
  "M8 job-level env CONFIRM literal": orig.replace("CONFIRM: ${{ inputs.confirm }}", "CONFIRM: ${{ inputs.confirm }}\n      CONFIRM2: x").replace(`test "$CONFIRM"`, `test "$CONFIRM2" = x || test "$CONFIRM"`),
  "M9 extra drop of another db via dropdb": orig.replace(`-c "CREATE DATABASE nihongo_bjt;"`, `-c "CREATE DATABASE nihongo_bjt;"\n          docker exec -u postgres oci-postgres-1 dropdb -U postgres keycloak`),
};
for (const [k,v] of Object.entries(muts)) console.log(k.padEnd(40), "t1:", t1(v).padEnd(22), "t2:", t2(v), v===orig && k!=="baseline" ? "(MUTATION NOT APPLIED)" : "");
'
